We have a legacy Node.js module `lib/order-processor.js` that handles order processing using nested callbacks. The module is used by our Express API and is hard to maintain. The code currently uses `fs.readFile` to load a JSON file, calls a third-party `validateOrder` function that returns a promise but we've wrapped it in callbacks, and then writes a receipt using `fs.writeFile`. The callbacks are causing callback hell and error handling is inconsistent. Our goal is to refactor the internal implementation to use async/await, making the code cleaner and more maintainable. The external API of the module (the exported function signature) must remain the same: `processOrder(orderData, callback)`. The callback should be Node-style (error first). Here is the current code:

```js
// lib/order-processor.js
const fs = require('fs');
const path = require('path');
const { validateOrder } = require('@acme/order-validation');

function processOrder(orderData, callback) {
  const orderId = orderData.id;
  const ordersPath = path.join(__dirname, '..', 'data', 'orders.json');
  fs.readFile(ordersPath, 'utf8', (err, fileData) => {
    if (err) return callback(err);
    let orders;
    try {
      orders = JSON.parse(fileData);
    } catch (parseErr) {
      return callback(parseErr);
    }
    // Simulate callback-based validation (actually promise-based)
    validateOrder(orderData, (valErr, isValid) => {
      if (valErr) return callback(valErr);
      if (!isValid) {
        const invErr = new Error('Order is invalid');
        invErr.code = 'INVALID_ORDER';
        return callback(invErr);
      }
      orders.push(orderData);
      const receiptPath = path.join(__dirname, '..', 'receipts', `receipt-${orderId}.txt`);
      fs.writeFile(receiptPath, `Receipt for order ${orderId}\n`, (writeErr) => {
        if (writeErr) return callback(writeErr);
        fs.writeFile(ordersPath, JSON.stringify(orders, null, 2), (finalErr) => {
          if (finalErr) return callback(finalErr);
          callback(null, { receiptPath, orderId });
        });
      });
    });
  });
}

module.exports = processOrder;
```

